// Deferred selected-profile chat commands; SQL queue only, never an actual window/DOM action.
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn telegram_browser_open_enqueues_one_current_selected_command_with_telegram_actor_and_no_fill_grant(){
 let(mut c,context,packet)=browser_command_fixture().await;let(settings,identity)=telegram_question_binding(&mut c).await;let text=format!("/browser open {} {}",packet["id"].as_str().unwrap(),packet["revision"]);assert!(telegram_answer_update(&mut c,&settings,&identity,telegram_update(300,&text)).await.unwrap());let rows:Vec<Value>=sqlx::query_scalar("SELECT value FROM owner_preferences WHERE starts_with(key,'chr_cmd:')").fetch_all(&mut c).await.unwrap();assert_eq!(rows.len(),1);assert_eq!(rows[0]["actor"],"telegram");assert_eq!(rows[0]["profile_binding_id"],context["profile_binding_id"]);assert_eq!(rows[0]["packet_revision"],packet["revision"]);assert_eq!(rows[0]["state"],"queued");assert_eq!(rows[0]["submitted"],false);let before=browser_snapshot(&mut c).await;assert!(!telegram_answer_update(&mut c,&settings,&identity,telegram_update(300,&text)).await.unwrap());assert_eq!(browser_snapshot(&mut c).await,before);assert_eq!(sqlx::query_scalar::<_,i64>("SELECT count(*) FROM owner_preferences WHERE starts_with(key,'fill_plan:') OR starts_with(key,'apply_budget:')").fetch_one(&mut c).await.unwrap(),0);
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn telegram_browser_offline_profile_refuses_command_without_creation_or_fallback(){
 let(mut c,context,packet)=browser_command_fixture().await;let(settings,identity)=telegram_question_binding(&mut c).await;let key=format!("chr_prof:{}",context["profile_binding_id"].as_str().unwrap());let mut profile=browser_pref(&mut c,&key).await;profile["connected"]=json!(false);browser_save(&mut c,&key,profile).await;let before=browser_snapshot(&mut c).await;assert!(telegram_answer_update(&mut c,&settings,&identity,telegram_update(310,&format!("/chrome open {} 1",packet["id"].as_str().unwrap()))).await.unwrap());assert_eq!(browser_snapshot(&mut c).await,before);let reply:String=sqlx::query_scalar("SELECT reply FROM agent_telegram_deliveries WHERE update_id=310").fetch_one(&mut c).await.unwrap();assert!(reply.contains("PROFILE_OFFLINE"));assert!(reply.contains("no browser fallback"));
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn telegram_browser_status_under_owner_lock_omits_profile_secrets_and_wrong_mention_is_inert(){
 let(mut c,_context,_packet)=browser_command_fixture().await;let(settings,identity)=telegram_question_binding(&mut c).await;let before=browser_snapshot(&mut c).await;let mut owner=connection().await;let mut tx=owner.begin().await.unwrap();sqlx::query("SELECT key FROM owner_preferences WHERE key='agent_conversation:primary' FOR UPDATE").execute(&mut *tx).await.unwrap();sqlx::query("SET lock_timeout='100ms'").execute(&mut c).await.unwrap();assert!(telegram_answer_update(&mut c,&settings,&identity,telegram_update(320,"/browser status")).await.unwrap());assert!(telegram_answer_update(&mut c,&settings,&identity,telegram_update(321,"/chrome@wrong_bot open 00000000-0000-4000-8000-000000000001 1")).await.unwrap());assert_eq!(browser_snapshot(&mut c).await,before);tx.rollback().await.unwrap();let replies:Vec<String>=sqlx::query_scalar("SELECT reply FROM agent_telegram_deliveries ORDER BY update_id").fetch_all(&mut c).await.unwrap();assert!(replies[0].contains("Selected browser:"));assert!(replies.iter().all(|s|!s.contains("profile_secret")&&!s.contains(&"f".repeat(64))));assert!(replies[1].starts_with("Use /browser"));
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn telegram_browser_cannot_adopt_same_nonce_command_created_by_different_actor(){
 let(mut c,context,packet)=browser_command_fixture().await;let(settings,identity)=telegram_question_binding(&mut c).await;let id=Uuid::new_v5(&Uuid::NAMESPACE_URL,b"chrome:telegram:22:330");let mut input=browser_enqueue_input(&context,&packet);input["request_id"]=json!(id);let queued=browser_call(&mut c,BrowserRoute::Enqueue,input).await.unwrap();assert_eq!(queued["actor"],"owner");let before=browser_snapshot(&mut c).await;assert!(telegram_answer_update(&mut c,&settings,&identity,telegram_update(330,&format!("/browser open {} 1",packet["id"].as_str().unwrap()))).await.unwrap());assert_eq!(browser_snapshot(&mut c).await,before);let reply:String=sqlx::query_scalar("SELECT reply FROM agent_telegram_deliveries WHERE update_id=330").fetch_one(&mut c).await.unwrap();assert!(reply.contains("command_id_conflict"));assert_eq!(browser_pref(&mut c,&format!("chr_cmd:{id}")).await,queued);
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn telegram_browser_stale_revision_and_unapproved_fill_action_leave_browser_authority_unchanged(){
 let(mut c,_context,packet)=browser_command_fixture().await;let(settings,identity)=telegram_question_binding(&mut c).await;let before=browser_snapshot(&mut c).await;for(index,action)in ["open","fill","submit","focus","settings"].iter().enumerate(){assert!(telegram_answer_update(&mut c,&settings,&identity,telegram_update(340+index as i64,&format!("/browser {action} {} 999",packet["id"].as_str().unwrap()))).await.unwrap());assert_eq!(browser_snapshot(&mut c).await,before);}assert_eq!(sqlx::query_scalar::<_,i64>("SELECT count(*) FROM owner_preferences WHERE starts_with(key,'chr_cmd:') OR starts_with(key,'fill_plan:')").fetch_one(&mut c).await.unwrap(),0);
}
